//! An imported integer that names `format: int32` or `int64` realizes at that native width, when
//! asked for with `BundleOptions::integer_format_widths` (beyond10x/ess#648). Without the option
//! every generated byte is the one 0.76.0 wrote.

use std::collections::BTreeSet;
use std::fmt::Write as _;

use schema_contract::bundle::{import, Bundle, Dialect};
use schema_contract::realize::{BundleOptions, Plan, Realization};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};

/// The reported shape: two integers that name a width and one bounded integer that names none.
fn counter() -> Value {
    json!({"Counter": {
        "type": "object",
        "properties": {
            "wide": {"type": "integer", "format": "int64"},
            "narrow": {"type": "integer", "format": "int32"},
            "bounded": {"type": "integer", "minimum": 0, "maximum": 100}
        },
        "required": ["wide", "narrow", "bounded"],
        "additionalProperties": false
    }})
}

fn bundle(schemas: &Value) -> (Bundle, BTreeSet<String>) {
    let roots = schemas
        .as_object()
        .unwrap()
        .keys()
        .cloned()
        .collect::<BTreeSet<_>>();
    let bundle = import(
        &json!({"components": {"schemas": schemas}}).to_string(),
        &roots,
        Dialect::Draft202012,
    )
    .unwrap();
    (bundle, roots)
}

/// The SHA-256 of every generated file, with the generator's own version taken out of the
/// declarations, the report and the build metadata, so a release bump does not move it.
fn digest(realization: &Realization) -> String {
    let version = env!("CARGO_PKG_VERSION");
    let masked = |text: &str| text.replace(version, "<version>");
    let mut report = serde_json::to_value(&realization.report).unwrap();
    report["generator_version"] = json!("<version>");
    let mut parts = vec![
        masked(&realization.declarations),
        serde_json::to_string_pretty(&report).unwrap(),
    ];
    for (name, contents) in &realization.supporting {
        parts.push(name.clone());
        parts.push(masked(contents));
    }
    let mut hasher = Sha256::new();
    for part in &parts {
        hasher.update(part.len().to_le_bytes());
        hasher.update(part.as_bytes());
    }
    hasher
        .finalize()
        .iter()
        .fold(String::new(), |mut hex, byte| {
            write!(hex, "{byte:02x}").unwrap();
            hex
        })
}

fn targets(plan: &Plan) -> [(&'static str, Realization); 3] {
    [
        ("rust", plan.rust("counter_types").unwrap()),
        (
            "go",
            plan.go("countertypes", "example.invalid/countertypes")
                .unwrap(),
        ),
        ("typescript", plan.typescript()),
    ]
}

/// Frozen from 0.76.0 before the option existed.
const DEFAULT_DIGESTS: [(&str, &str); 3] = [
    (
        "rust",
        "0144ea0a19b17ce1726082f980a9b048a51f92d19ca7fc5b9cb5ae114abda479",
    ),
    (
        "go",
        "c31fe11819ec29c08cd8981839f69e8da6c50dd5e11a2983dcbc75b1851fccd7",
    ),
    (
        "typescript",
        "5abe1cfa3044dab8a57e099a69e3128b29d3c7823ed96f92943338b303e70e53",
    ),
];

const WIDTHS: BundleOptions = BundleOptions {
    integer_format_widths: true,
};

fn plan(schemas: &Value, options: BundleOptions) -> Plan {
    let (bundle, roots) = bundle(schemas);
    Plan::from_bundle_with(&bundle, &roots, &options).unwrap()
}

/// Each field's declared line, by the name that starts it.
fn field_line<'a>(declarations: &'a str, field: &str) -> &'a str {
    declarations
        .lines()
        .find(|line| line.trim_start().starts_with(field))
        .unwrap_or_else(|| panic!("no `{field}` in:\n{declarations}"))
}

fn rust_and_go(plan: &Plan) -> (String, String) {
    (
        plan.rust("counter_types").unwrap().declarations,
        plan.go("countertypes", "example.invalid/countertypes")
            .unwrap()
            .declarations,
    )
}

fn findings(realization: &Realization, list: &str) -> BTreeSet<(String, String, String)> {
    let report = serde_json::to_value(&realization.report).unwrap();
    report[list]
        .as_array()
        .unwrap()
        .iter()
        .map(|finding| {
            (
                finding["pointer"].as_str().unwrap().to_owned(),
                finding["rule"].as_str().unwrap().to_owned(),
                finding["detail"].as_str().unwrap().to_owned(),
            )
        })
        .collect()
}

fn rules_at(realization: &Realization, pointer: &str) -> BTreeSet<String> {
    findings(realization, "obligations")
        .into_iter()
        .filter(|(at, _, _)| at == pointer)
        .map(|(_, rule, _)| rule)
        .collect()
}

const PROPERTIES: &str = "/components/schemas/Counter/properties";

#[test]
fn the_default_output_keeps_its_bytes() {
    let (bundle, roots) = bundle(&counter());
    let plans = [
        Plan::from_bundle(&bundle, &roots).unwrap(),
        Plan::from_bundle_with(&bundle, &roots, &BundleOptions::default()).unwrap(),
    ];
    for plan in &plans {
        let realizations = targets(plan);
        let digests = realizations
            .iter()
            .map(|(target, realization)| (*target, digest(realization)))
            .collect::<Vec<_>>();
        assert_eq!(
            digests,
            DEFAULT_DIGESTS.map(|(target, frozen)| (target, frozen.to_owned())),
            "{}",
            realizations
                .iter()
                .map(|(target, realization)| format!("{target}:\n{}", realization.declarations))
                .collect::<Vec<_>>()
                .concat()
        );
    }
}

#[test]
fn an_imported_int64_realizes_as_i64() {
    let (rust, go) = rust_and_go(&plan(&counter(), WIDTHS));
    assert!(field_line(&rust, "pub wide:").ends_with(" i64,"), "{rust}");
    assert!(
        field_line(&rust, "pub narrow:").ends_with(" i32,"),
        "{rust}"
    );
    assert!(field_line(&go, "Wide ").contains(" int64"), "{go}");
    assert!(field_line(&go, "Narrow ").contains(" int32"), "{go}");
}

#[test]
fn an_imported_integer_without_format_keeps_the_exact_number_type() {
    let plan = plan(&counter(), WIDTHS);
    let (rust, go) = rust_and_go(&plan);
    assert!(
        field_line(&rust, "pub bounded:").ends_with(" ::serde_json::Number,"),
        "{rust}"
    );
    assert!(field_line(&go, "Bounded ").contains(" EssNumber"), "{go}");
    let pointer = format!("{PROPERTIES}/bounded");
    for realization in [
        plan.rust("counter_types").unwrap(),
        plan.go("countertypes", "example.invalid/countertypes")
            .unwrap(),
    ] {
        assert!(
            rules_at(&realization, &pointer).contains("integer"),
            "{:?}",
            findings(&realization, "obligations")
        );
    }
}

#[test]
fn an_unknown_integer_format_keeps_the_exact_number_type() {
    let schemas = json!({"Counter": {
        "type": "object",
        "properties": {
            "unsigned": {"type": "integer", "format": "uint64"},
            "tiny": {"type": "integer", "format": "int8"}
        },
        "required": ["unsigned", "tiny"],
        "additionalProperties": false
    }});
    let (rust, go) = rust_and_go(&plan(&schemas, WIDTHS));
    for field in ["unsigned", "tiny"] {
        assert!(
            field_line(&rust, &format!("pub {field}:")).ends_with(" ::serde_json::Number,"),
            "{rust}"
        );
    }
    for field in ["Unsigned ", "Tiny "] {
        assert!(field_line(&go, field).contains(" EssNumber"), "{go}");
    }
}

#[test]
fn a_format_width_holds_beside_bounds() {
    let schemas = json!({"Counter": {
        "type": "object",
        "properties": {"small": {"type": "integer", "format": "int64", "minimum": 0, "maximum": 10}},
        "required": ["small"],
        "additionalProperties": false
    }});
    let plan = plan(&schemas, WIDTHS);
    let (rust, go) = rust_and_go(&plan);
    assert!(field_line(&rust, "pub small:").ends_with(" i64,"), "{rust}");
    assert!(field_line(&go, "Small ").contains(" int64"), "{go}");
    let realization = plan.rust("counter_types").unwrap();
    for keyword in ["minimum", "maximum"] {
        assert!(
            rules_at(&realization, &format!("{PROPERTIES}/small/{keyword}")).contains(keyword),
            "{:?}",
            findings(&realization, "obligations")
        );
    }
}

#[test]
fn a_nullable_int64_realizes_as_an_optional_i64() {
    let schemas = json!({"Counter": {
        "type": "object",
        "properties": {"maybe": {"type": ["integer", "null"], "format": "int64"}},
        "required": ["maybe"],
        "additionalProperties": false
    }});
    let (rust, go) = rust_and_go(&plan(&schemas, WIDTHS));
    assert!(
        field_line(&rust, "pub maybe:").ends_with(" ::std::option::Option<i64>,"),
        "{rust}"
    );
    assert!(
        field_line(&go, "Maybe ").contains(" EssNullable[int64]"),
        "{go}"
    );
}

/// The Go module refuses each value outside the named width; the Rust half, which builds the
/// generated crate, is the test of the same name in `model_ergonomics.rs`, the test file allowed
/// to run cargo.
#[test]
fn the_decoder_refuses_a_value_outside_the_format_range() {
    use std::process::Command;
    let realization = plan(&counter(), WIDTHS)
        .go("countertypes", "example.invalid/countertypes")
        .unwrap();
    if Command::new("go").arg("version").output().is_err() {
        println!("skipped compiling: no `go` on PATH");
        return;
    }
    let root = std::path::Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join(format!("bundle-integer-formats-go-{}", std::process::id()));
    std::fs::create_dir_all(&root).unwrap();
    std::fs::write(root.join("go.mod"), &realization.supporting["go.mod"]).unwrap();
    std::fs::write(root.join("types.go"), &realization.declarations).unwrap();
    std::fs::write(root.join("range_test.go"), GO_RANGE_TEST).unwrap();
    let output = Command::new("go")
        .args(["test", "."])
        .current_dir(&root)
        .env("GOFLAGS", "-mod=mod")
        .env("GOPROXY", "off")
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "{}\n{}\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr),
        realization.declarations
    );
}

const GO_RANGE_TEST: &str = r#"package countertypes

import (
	"encoding/json"
	"testing"
)

func TestTheDecoderRefusesAValueOutsideTheFormatRange(t *testing.T) {
	var edge Counter
	if err := json.Unmarshal([]byte(`{"wide":9223372036854775807,"narrow":2147483647,"bounded":1}`), &edge); err != nil {
		t.Fatal(err)
	}
	if edge.Wide != 9223372036854775807 || edge.Narrow != 2147483647 {
		t.Fatalf("edge values: %+v", edge)
	}
	for _, text := range []string{
		`{"wide":1,"narrow":2147483648,"bounded":1}`,
		`{"wide":9223372036854775808,"narrow":1,"bounded":1}`,
		`{"wide":1.5,"narrow":1,"bounded":1}`,
	} {
		var counter Counter
		if err := json.Unmarshal([]byte(text), &counter); err == nil {
			t.Fatalf("accepted %s as %+v", text, counter)
		}
	}
}
"#;

#[test]
fn the_report_records_the_option_and_names_the_asserted_format() {
    let detail =
        "the decoder asserts this format's range (accepted with the integer-format-widths \
                  option); `validate-bundle` treats `format` as an annotation";
    // TypeScript decodes nothing: the range is the consumer's, as an obligation.
    let typescript_detail = "TypeScript declares `number` and has no decoder, so the consumer \
                             enforces this format's range (`typescript_integer_range`); \
                             `validate-bundle` treats `format` as an annotation";
    let default = plan(&counter(), BundleOptions::default());
    let widths = plan(&counter(), WIDTHS);
    for (default, widths) in targets(&default).iter().zip(targets(&widths).iter()) {
        let target = default.0;
        let off = serde_json::to_value(&default.1.report).unwrap();
        let on = serde_json::to_value(&widths.1.report).unwrap();
        assert!(off.get("options").is_none(), "{target}: {off}");
        assert_eq!(
            on["options"],
            json!({"integer_format_widths": true}),
            "{target}"
        );
        for field in ["wide", "narrow"] {
            let pointer = format!("{PROPERTIES}/{field}/format");
            let annotation = findings(&widths.1, "annotations")
                .into_iter()
                .find(|(at, _, _)| *at == pointer)
                .unwrap_or_else(|| panic!("{target}: no annotation at {pointer}"));
            assert_eq!(annotation.1, "format");
            let expected = if target == "typescript" {
                typescript_detail
            } else {
                detail
            };
            assert_eq!(annotation.2, expected, "{target}");
            let unchanged = findings(&default.1, "annotations")
                .into_iter()
                .find(|(at, _, _)| *at == pointer)
                .unwrap();
            assert_eq!(
                unchanged.2,
                "retained in the source bundle; no decoder behavior inferred"
            );
        }
        if target != "typescript" {
            for field in ["wide", "narrow"] {
                let pointer = format!("{PROPERTIES}/{field}");
                let rules = rules_at(&widths.1, &pointer);
                assert!(
                    !rules.contains("integer") && !rules.contains("rust_exact_numbers"),
                    "{target}: {rules:?}"
                );
                assert!(
                    rules_at(&default.1, &pointer).contains("integer"),
                    "{target}"
                );
            }
        }
    }
    let typescript = |plan: &Plan| plan.typescript();
    let narrow = format!("{PROPERTIES}/narrow");
    assert!(rules_at(&typescript(&default), &narrow).contains("json_number_precision"));
    assert!(!rules_at(&typescript(&widths), &narrow).contains("json_number_precision"));
    assert!(
        rules_at(&typescript(&widths), &format!("{PROPERTIES}/wide"))
            .contains("json_number_precision")
    );
    for field in ["wide", "narrow"] {
        let pointer = format!("{PROPERTIES}/{field}");
        assert!(rules_at(&typescript(&widths), &pointer).contains("typescript_integer_range"));
        assert!(!rules_at(&typescript(&default), &pointer).contains("typescript_integer_range"));
    }
}

#[test]
fn a_bundle_whose_integers_all_name_a_width_gets_no_exact_numbers_feature() {
    let schemas = json!({"Counter": {
        "type": "object",
        "properties": {
            "wide": {"type": "integer", "format": "int64"},
            "narrow": {"type": "integer", "format": "int32"}
        },
        "required": ["wide", "narrow"],
        "additionalProperties": false
    }});
    let manifest = |options: BundleOptions| {
        plan(&schemas, options)
            .rust("counter_types")
            .unwrap()
            .supporting["Cargo.toml"]
            .clone()
    };
    let with = manifest(WIDTHS);
    assert!(!with.contains("exact-numbers"), "{with}");
    assert!(!with.contains("arbitrary_precision"), "{with}");
    let without = manifest(BundleOptions::default());
    assert!(without.contains("exact-numbers"), "{without}");
}

#[test]
fn validate_bundle_still_treats_format_as_an_annotation() {
    let (bundle, _) = bundle(&counter());
    for instance in [
        json!({"wide": 1, "narrow": 2_147_483_648_u64, "bounded": 1}),
        json!({"wide": 9_223_372_036_854_775_808_u64, "narrow": 1, "bounded": 1}),
    ] {
        assert_eq!(
            bundle.validate("Counter", &instance).unwrap(),
            [],
            "{instance}"
        );
    }
    assert_ne!(
        bundle
            .validate("Counter", &json!({"wide": 1.5, "narrow": 1, "bounded": 1}))
            .unwrap(),
        []
    );
}
